mapper.select:
select * from ( SELECT a.event_id eventId, a.warn_id warnId, a.ecg_id ecgId, a.event_type_id eventTypeId, a.event_timestamp eventTimestamp, a.event_start_time eventStartTime, a.event_end_time eventEndTime, a.bpm , a.warn_level warnLevel, ifnull(a.confirm_status,0) confirmStatus, a.confirm_time confirmTime, a.confirm_user_id confirmUserId, b.code_name eventTypeName, c.age, d.user_name userName, d.user_gender userGender, d.user_tel userTel, c.user_id userId FROM cust_user_warning_event a LEFT JOIN comm_base_code_detail b ON a.event_type_id=b.code_id AND b.type_no='CD200' LEFT JOIN cust_user_ecg_rec c ON a.ecg_id=c.ecg_id LEFT JOIN cust_userinfo d ON c.user_id=d.user_id )temp where 1=1
AND warnLevel=#{tm}
and confirmStatus=#{tm}
and from_unixtime(eventTimestamp/1000,'%Y-%m-%d') >= #{tm}
and from_unixtime(eventTimestamp/1000,'%Y-%m-%d') <= #{tm}
and ${key} like CONCAT('%',#{tm,jdbcType=VARCHAR}, '%')
order by ${column} ${order}
order by eventTimestamp desc
